INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Jurassic Wrap', 'Rescue baby dino eggs in a family-friendly adventure made by a father & son duo. In Jurassic Wrap, your goal is simple: save the baby dino eggs and make it safely to the exit portal. Along the way you''ll leap, dodge, and use clever screen-wrapping mechanics to outsmart threats through each level.' FROM games WHERE igdb_id = 381736 ON CONFLICT (game_id, language_code) DO NOTHING;
