INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'King of Silence', 'Every noise has a consequence you don''t want to know about. Hold your breath and immerse yourself in King Of Silence, a 1st person horrific experience where the strange, the superstitious and the frightening are combined.' FROM games WHERE igdb_id = 254049 ON CONFLICT (game_id, language_code) DO NOTHING;
