INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('asuka-120-percent-burning-fest-exallent', 382789, '2025-12-24', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cob42n.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc10zri.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Asuka 120% Burning Fest. Exallent', 'The original anime fighter finally returns! Working with the series’ original designer, Masatoshi Imaizumi, Asuka 120% BURNING Fest. EXALLENT brings back the whole cast from every title in the series. Each character has all of their special moves from past games and also newly added animated special moves as well as the devastating new super moves called EXALLENT NOVA. Background characters are now animated and each stage is accompanied by a new soundtrack by returning series composer, Keishi Yonao. 5 soundtracks are included so you can choose your favorite arrangement before each match. Series vocalist, Reika, is also back singing the new theme song, Do Not. Renowned illustrator and animator from the Urusei Yatsura and Ranma 1/2 reboots, Yo-co brings her stylish 90’s style to the classic Asuka 120% character designs. The story mode is also now fully translated into English for the first time ever! Based upon the fan favorites, utilize clashes and evades to gain an advantage. Move through the air using various types of jumps and cancels to surprise your opponent. Cancel a wide variety of movements like your guard stun, jumps and even specials to keep the pressure up. All of the advanced movement mechanics expected in a modern fighter are all here. Take advantage of the Training Mode to practice real battle situations and optimize your combos.' FROM games WHERE igdb_id = 382789 ON CONFLICT (game_id, language_code) DO NOTHING;
