INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Smoke', 'The Smoke is a 2D Metroidvania where players wield a gun to disperse the smoke that threatens to engulf the world. Explore a world filled with hidden pathways and treacherous chambers. Blast away enemies, clear toxic clouds, and unlock new abilities. Stop the darkness before it swallows everything.' FROM games WHERE igdb_id = 365530 ON CONFLICT (game_id, language_code) DO NOTHING;
