INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'BitLiberator', 'BitLiberator is a strategy/puzzle/action game where you eliminate corrupted Programs by either destroying them or reprogramming them. You can control friendly reprogrammed Programs and connect them into more powerful structures. You can also apply Upgrades to your Programs, allowing them to perform actions such as shooting enemies, shielding themselves from enemy fire, or slowing enemies down. However, be warned that, over time, corrupted Programs will detect you and start moving toward you.' FROM games WHERE igdb_id = 340036 ON CONFLICT (game_id, language_code) DO NOTHING;
