INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monster House Racing', 'Monster House Racing invites you to rev your engines and speed through the haunted corridors of the Grindstone Manor in this exhilarating kart racing game. Embrace the Halloween spirit as you compete against friends and AI opponents in thrilling races across ghostly tracks filled with supernatural challenges and spooky surprises. Whether you''re a seasoned racer or new to the track, Monster House Racing offers a heart-pounding experience perfect for any fan of high-speed action and haunted thrills.' FROM games WHERE igdb_id = 376708 ON CONFLICT (game_id, language_code) DO NOTHING;
