INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bullet Yeeters', 'Bullet Yeeters is a third-person shooter where miniature agents navigate oversized household environments using jetpacks. Players engage in combat across domestic settings like kitchens and living rooms, face boss encounters, and can modify their characters'' appearances and loadouts. The game emphasizes aerial mobility and firefights within familiar spaces transformed into battlegrounds.' FROM games WHERE igdb_id = 338894 ON CONFLICT (game_id, language_code) DO NOTHING;
