INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Generation Exile', 'Generation Exile is a turn-based city-builder taking place aboard a generation starship where instead of extracting more and more natural resources to meet your populace’s needs, you only have what you brought with you. Rebuild the ship’s fragile ecosystems before the ship reaches the end of its journey. Procedurally generated characters and storylines mean that every journey — spanning several hundred years — will be uniquely yours.' FROM games WHERE igdb_id = 305182 ON CONFLICT (game_id, language_code) DO NOTHING;
