INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Gorn 2', 'GORN 2 is a ludicrous sequel to the hit VR gladiator simulator from Free Lives. It''s bigger, wilder, and stronger than ever before, with mighty new weapons to wield, treacherous new traps to avoid, and new power-ups to imbue you with supernatural strength. Enjoy GORN 2''s improved VR combat as you battle the five sons of the God of the Afterlife across an array of heavenly realms, with in-your-face combat so irresponsibly violent you''ll check your headset for blood spatters when you''re done.' FROM games WHERE igdb_id = 333676 ON CONFLICT (game_id, language_code) DO NOTHING;
