INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Exit Together', 'Exit Together is a 1-6 player co-op or single-player anomaly loop adventure game. Find anomalies, solve puzzles, and avoid traps. Set in a retro 1960s office atmosphere, observe your surroundings carefully to reach the next room. Will you reach Room 9 and exit, or remain trapped forever in the loop?' FROM games WHERE igdb_id = 333662 ON CONFLICT (game_id, language_code) DO NOTHING;
