INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Matchmaker: Dungeon Heart', 'Matchmaker: Dungeon Heart is a narrative-driven dating & romance sim featuring match-3 gameplay. As powerful forces draw near, a Lich raises you from the dead, and tasks you with protecting the dungeons of Torkadall. As you train with the monstrous inhabitants, you may find yourself falling in love.' FROM games WHERE igdb_id = 263783 ON CONFLICT (game_id, language_code) DO NOTHING;
