INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'The Rogue Prince of Persia', 'The Rogue Prince of Persia is a 2D action-platformer developed by Evil Empire in collaboration with Ubisoft. The game combines fast-paced parkour movement with roguelite combat and progression systems. Players control the Prince as he battles enemies and explores procedurally generated levels filled with traps and hazards.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 296843 AND ge.slug = 'platform' ON CONFLICT DO NOTHING;
