INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('anomaly-seeker-the-diner', 343123, '2025-05-31', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co9sec.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/ar3m82.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Anomaly Seeker: The Diner', 'Step into the world of Anomaly Seeker: The Diner, a thrilling anomaly detection puzzle game that tests your attention to detail and memory! Set in a charming and atmospheric diner, you’ll need to carefully examine the room and identify hidden anomalies. But the challenge doesn’t stop there—on your next visit, the room may look the same, but there’s a twist! You’ll need to recall the details and determine if something’s changed. Only the most observant will be able to find all the anomalies and solve the mysteries lurking within. Featuring 27 anomalies. Can you find them all?' FROM games WHERE igdb_id = 343123 ON CONFLICT (game_id, language_code) DO NOTHING;
