INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'H Index', 'The Earth''s poles began to change places, and this caused chaos. People sensitive to the changes become aggressive and start attacking each other. Scientific minds have created the Hindex scale, which shows the level of activity of storms on a 12-point system.' FROM games WHERE igdb_id = 340474 ON CONFLICT (game_id, language_code) DO NOTHING;
