INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hopward', 'Hopward is a precision platformer where you play as a determined little frog climbing toward the sky. Charge your jumps, dive through the air, and test your patience as every leap brings you closer to the top or all the way back to the bottom. Explore vibrant worlds from rainy ponds to wizard towers, floating gardens, and mystical skies.INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 372475 AND ge.slug = 'platform' ON CONFLICT DO NOTHING;
