INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Path of the Zenith Master', 'Path of the Zenith Master is an action-adventure game. Once a disciple of a reclusive mountain clan, you are chosen to forge your own path to mastery when your clan faces imminent peril. Through trials of fire and steel, transform into the unyielding pillar that safeguards your ancestral stronghold.' FROM games WHERE igdb_id = 372016 ON CONFLICT (game_id, language_code) DO NOTHING;
