INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Momochan''s Brain is So Crazy!', 'Momo is a silly cat who can only move! Avoid enemies and collect cat food cans to reach the goal. If you hit an obstacle or fall, it''s game over! Your score is cans collected minus time elapsed. Clear all 20 stages in this simple yet challenging action game. Can you lead Momo to victory?' FROM games WHERE igdb_id = 388979 ON CONFLICT (game_id, language_code) DO NOTHING;
