INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('spot-the-pup', 379296, '2025-11-05', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/cobhpz.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/sc11p81.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Spot The Pup', 'Get ready to put your eyes to the test and your heart on full display in Spot The Pup, the ultimate hidden object adventure for dog lovers! Each scene bursts with charm, color, and chaos as you hunt for ten mischievous pups tucked into unexpected places. Whether you’re racing the clock in Challenge Mode or taking a relaxed stroll through Casual Mode, every level promises a delightful mix of discovery, relaxation, and pure puppy joy. Gamers will care because Spot The Pup isn’t just about finding dogs, it’s about finding moments of happiness. With its cozy visuals, easy to learn mechanics, and addictive “just one more level” feeling, it’s the perfect escape for anyone who loves puzzles, pets, or simply a feel good gaming experience.' FROM games WHERE igdb_id = 379296 ON CONFLICT (game_id, language_code) DO NOTHING;
