INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Monkey Lost', 'Players guide a playful young monkey through lush, vibrant jungles filled with colorful animal companions. At its core, Monkey Lost tells a story of friendship, perseverance, and the search for home. With its charming characters, delightful visuals, and family-friendly design, the game offers a jungle journey that appeals to players of all ages.' FROM games WHERE igdb_id = 367452 ON CONFLICT (game_id, language_code) DO NOTHING;
