INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'AFL 26', 'Get ready for the future of footy with AFL 26. Feel every hit, hear every roar, and live every moment with unmatched authenticity and intensity. From the first bounce to the final siren, the action is fast, fierce, and true to the game. With lifelike gameplay, roaring crowds, expert commentary, and all the drama of real AFL, you’re not just watching the game — you’re in it. This is footy, redefined.' FROM games WHERE igdb_id = 340723 ON CONFLICT (game_id, language_code) DO NOTHING;
