INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Kyoto Anomaly', 'Kyoto Anomaly is an anomaly detection game, inspired by games like The Exit 8, Platform 8 and Shinkansen 0. The player finds themselves trapped in the endless maze of Kyoto''s backstreets, trying to reach the temple of Hōkan-ji before the main tourist rush. Inspect the street for anomalies, choose the right path, and reach your destination… or be trapped forever.' FROM games WHERE igdb_id = 342108 ON CONFLICT (game_id, language_code) DO NOTHING;
