INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Hentai Shop Simulator', 'Ever dreamt of running a shop that’s a little… spicier? In Hentai Shop Simulator, you’re the proud owner of a one-of-a-kind store catering to anime fans with a taste for the bold. Stock shelves with eye-catching magazines and cheeky merchandise, manage your inventory like a pro, and watch your profits soar. Just remember—your niche is adult content, so keep it classy...ish.' FROM games WHERE igdb_id = 338002 ON CONFLICT (game_id, language_code) DO NOTHING;
