INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Heat Me Up!', 'Feeling the chill? Heat things up with Heat Me Up!, the fiery arcade game where you control Flamy, a super-heated iron ball on a mission to stay hot! Guide Flamy by placing your finger on the screen – it''s his personal launchpad! Tap below him to make him jump onto your finger, then skillfully slide your finger left or right to add momentum and direction, propelling him through the air. Collect blazing fire orbs to keep his temperature up, but watch out for those frosty yetis – they''re not fans of Flamy''s heat! Get ready for a scorching hot challenge that will keep you coming back for more. Download Heat Me Up! and turn up the heat!' FROM games WHERE igdb_id = 378385 ON CONFLICT (game_id, language_code) DO NOTHING;
