INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Prophecrawl', 'In this dystopian nightmare, soldiers track the Anomaly—a shape-shifting enigma that clones itself, warps reality, and mimics human speech. Communicate with your squad, queue up for online missions, but remember: it’s not just a hunt; it’s a frantic race against time.' FROM games WHERE igdb_id = 341260 ON CONFLICT (game_id, language_code) DO NOTHING;
INSERT INTO game_genres (game_id, genre_id) SELECT g.id, ge.id FROM games g, genres ge WHERE g.igdb_id = 341260 AND ge.slug = 'strategy' ON CONFLICT DO NOTHING;